render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$x, y = cfg$y, group = 1)) + ggplot2::geom_area(fill = cfg$color %||% "#0A84FF", alpha = 0.35) + ggplot2::geom_line(colour = cfg$color %||% "#0A84FF", linewidth = 1) + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$x, y = cfg$y); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
